export const CODING_TOPIC_PACKS: CodingTopicPack[] = RAW_PACKS.map((p) => ({
  ...p,
  docs: p.docs.map((d) => buildDoc(d.id, d.title, d.meta, d.turns, d.kind)),
}));

export const CODING_TOPIC_BY_ID: Record<string, CodingTopicPack> = Object.fromEntries(
  CODING_TOPIC_PACKS.map((p) => [p.id, p]),
);

/** 주제 팩용 1차 코딩 — 표지 낱말로 시드. */
export function seedAssignForPack(pack: CodingTopicPack): Assign {
  const codes = pack.themes.flatMap((t) => t.codes);
  const raw: [RegExp, string][] = [
    [/목표|한 줄|정리/, codes[0]?.id || ""],
    [/바로|확인|피드백/, codes[1]?.id || ""],
    [/관계|지지|혼자/, codes[2]?.id || ""],
    [/느낌|정서|의미/, codes[3]?.id || codes[0]?.id || ""],
    [/통제|선택/, codes[5]?.id || codes[1]?.id || ""],
    [/알림|방해|깨/, codes[6]?.id || ""],
    [/평가|비교|규범/, codes[7]?.id || ""],
    [/자원|부족/, codes[8]?.id || ""],
  ];
  const byHint = raw.filter((x): x is [RegExp, string] => Boolean(x[1]));

  const out: Assign = {};
  for (const d of pack.docs) {
    for (const s of d.segs) {
      if (s.who !== "P") continue;
      for (const [re, cid] of byHint) {
        if (re.test(s.text)) {
          out[s.id] = [cid];
          break;
        }
      }
    }
  }
  return out;
}
